import {AlertFillIcon, CopilotIcon} from '@primer/octicons-react'
import {Spinner} from '@primer/react'
import {clsx} from 'clsx'
import type React from 'react'

import styles from './CopilotBadge.module.css'

export interface CopilotBadgeProps {
  isLoading?: boolean
  isError?: boolean
  hasUnreadMessages?: boolean
  /** CSS color value or CSS variable, e.g. `var(--fgColor-accent)` */
  fill?: string
  /** CSS color value or CSS variable, e.g. `var(--bgColor-muted)` */
  bg?: string
  /** CSS color value or CSS variable, e.g. `var(--borderColor-default)` */
  borderColor?: string
  customIcon?: React.ReactNode
}

export default function CopilotBadge(props: CopilotBadgeProps) {
  const {isLoading, isError, hasUnreadMessages, fill, bg, borderColor, customIcon} = props

  const dynamicStyle: React.CSSProperties = {
    ...(bg ? {backgroundColor: bg} : undefined),
    ...(borderColor ? {borderColor} : undefined),
    ...(fill ? {color: fill} : undefined),
  }

  return (
    <div
      className={clsx(
        styles.CopilotBadgeContainer,
        isError && !bg && styles.errorBg,
        isLoading && !fill && styles.loadingColor,
      )}
      style={bg || borderColor || fill ? dynamicStyle : undefined}
    >
      <div className={clsx(styles.spinnerContainer, isLoading && styles.spinnerVisible)}>
        <Spinner size="medium" className={styles.loadingSpinner} />
      </div>
      {hasUnreadMessages && <div className={clsx('unread-indicator', styles.unreadIndicator)} />}
      {customIcon ? customIcon : <CopilotIcon size={12} />}
      {isError ? (
        <div className={styles.attentionIndicator}>
          <AlertFillIcon size={12} />
        </div>
      ) : null}
    </div>
  )
}
